const $=id=>document.getElementById(id),desktop=window.cutoutDesktop;
const titles={cutout:'Supprimer le fond.',upscale:'Voir plus grand.',erase:'Enlever l’intrus.',compose:'Créer autrement.'};
let tool='cutout',source,working,mask,name='',sourceData='',sourceType='',busy=false,ready=!desktop,history=[],detected=[],selectedLayer=null,assetKind='',compare=false,saveTimer,project={background:null,backgroundImage:null,layers:[]};
let editTool='move',penNodes=[],penClosed=false,cropBox=null,redoHistory=[];
const documentRecords=new Map();let activeDocumentId=crypto.randomUUID();
const assets=new Map();const screen=$('canvas'),overlay=$('overlay');
const status=m=>{$('status').textContent=typeof m==='string'?(/Mac|iPhone|iPad/.test(navigator.platform)?m.replaceAll('Alt + clic','Option ⌥ + clic'):m):'';};
const dataURL=blob=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Image illisible.'));r.readAsDataURL(blob);});
const pngData=c=>c.toDataURL('image/png');
function lock(value){busy=value;document.querySelectorAll('button,input,select').forEach(e=>e.disabled=value);if(!value){document.querySelectorAll('.requires-image').forEach(e=>e.disabled=!working);$('undo').disabled=!history.length;$('original').disabled=!working;}$('progress').hidden=!value;if(value)$('progress').removeAttribute('value');}
function openTool(next){if(busy||!ready)return;leaveDesign();tool=next;$('home').hidden=true;$('editor').hidden=false;document.querySelectorAll('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==tool);document.querySelectorAll('.tool-tabs [data-tool]').forEach(b=>b.setAttribute('aria-current',b.dataset.tool===tool?'page':'false'));$('tool-title').textContent=titles[tool];ensureBase();compare=false;$('original').textContent='Voir l’original';draw();update();scheduleSave();}
function home(){if(busy||!ready)return;leaveDesign();$('home').hidden=false;$('editor').hidden=true;}
function ensureBase(){if(!working||project.layers.some(l=>l.kind==='base'))return;project.layers.unshift({id:'base',kind:'base',name:'Image principale',x:working.width/2,y:working.height/2,width:working.width,height:working.height,rotation:0,scale:1,opacity:1});}
function layerContent(l){
 const b=layerBounds(l),c=makeCanvas(Math.max(1,Math.ceil(b.w)),Math.max(1,Math.ceil(b.h))),ctx=c.getContext('2d');
 if(l.kind==='text'){
  if(l.textBackground){ctx.fillStyle=l.textBackground;ctx.fillRect(0,0,c.width,c.height);}
  drawTextEffects(ctx,l);
 }else if(l.kind==='gradient'){ctx.fillStyle=midpointGradient(ctx,l.gradient,c.width,c.height);ctx.fillRect(0,0,c.width,c.height);}
 else{const asset=l.kind==='base'?working:assets.get(l.data);if(asset)ctx.drawImage(asset,0,0,c.width,c.height);}
 if(l.gradient&&l.kind!=='gradient'){ctx.globalCompositeOperation='source-in';ctx.fillStyle=midpointGradient(ctx,l.gradient,c.width,c.height);ctx.fillRect(0,0,c.width,c.height);ctx.globalCompositeOperation='source-over';}
 if(l.maskData&&!l.maskDisabled){const maskImage=assets.get(l.maskData);if(maskImage){ctx.globalCompositeOperation='destination-in';ctx.drawImage(maskImage,0,0,c.width,c.height);ctx.globalCompositeOperation='source-over';}}
 return c;
}
function drawLayer(ctx,l){if(l.visible===false)return;const c=layerContent(l);ctx.save();ctx.translate(l.x,l.y);ctx.rotate(l.rotation*Math.PI/180);ctx.scale(l.scale*(l.flipX?-1:1),l.scale*(l.flipY?-1:1));ctx.globalAlpha=l.opacity;ctx.globalCompositeOperation=l.blend||'source-over';ctx.filter=`brightness(${l.brightness??100}%) contrast(${l.contrast??100}%) saturate(${l.saturation??100}%)`;ctx.drawImage(c,-c.width/2,-c.height/2);ctx.restore();}
function render(target,withProject=tool==='compose'){
 const ctx=target.getContext('2d');ctx.clearRect(0,0,target.width,target.height);if(!working)return;
 if(compare){ctx.drawImage(source,0,0,target.width,target.height);return;}
 if(!withProject){ctx.drawImage(working,0,0);return;}ensureBase();
 if(project.background){ctx.fillStyle=project.background;ctx.fillRect(0,0,target.width,target.height);}
 if(project.backgroundImage){const bg=assets.get(project.backgroundImage);if(bg){const k=Math.max(target.width/bg.width,target.height/bg.height);ctx.drawImage(bg,(target.width-bg.width*k)/2,(target.height-bg.height*k)/2,bg.width*k,bg.height*k);}}
 for(const l of project.layers)drawLayer(ctx,l);
}
function fit(){if(!working)return;const rect=$('drop').getBoundingClientRect();const scale=Math.min((rect.width-52)/working.width,(rect.height-52)/working.height,1);$('canvas-wrap').style.width=Math.max(1,Math.floor(working.width*scale))+'px';$('canvas-wrap').style.height=Math.max(1,Math.floor(working.height*scale))+'px';screen.style.width='100%';screen.style.height='100%';}
function draw(){if(!working)return;$('canvas-wrap').hidden=false;$('empty').hidden=true;if(screen.width!==working.width||screen.height!==working.height){screen.width=working.width;screen.height=working.height;overlay.width=working.width;overlay.height=working.height;}render(screen);drawOverlay();fit();}
function drawOverlay(){const ctx=overlay.getContext('2d');ctx.clearRect(0,0,overlay.width,overlay.height);if(compare)return;if(tool==='erase'&&mask){ctx.globalAlpha=.45;ctx.drawImage(mask,0,0);ctx.globalAlpha=1;}if(tool==='compose'&&selectedLayer){const l=project.layers.find(l=>l.id===selectedLayer);if(l){const bounds=layerBounds(l);ctx.save();ctx.translate(l.x,l.y);ctx.rotate(l.rotation*Math.PI/180);ctx.scale(l.scale,l.scale);ctx.strokeStyle='#f01813';ctx.lineWidth=Math.max(2,working.width/500)/l.scale;ctx.setLineDash([8/l.scale,5/l.scale]);ctx.strokeRect(-bounds.w/2,-bounds.h/2,bounds.w,bounds.h);ctx.restore();}}}
function fontString(l){return `${l.italic?'italic ':''}${l.weight||800} ${l.fontSize}px '${l.font}'`;}
function layerBounds(l){return l.kind==='text'?textLayout(screen.getContext('2d'),l):{w:l.width,h:l.height};}
function update(){renderDocumentTabs();document.querySelectorAll('.requires-image').forEach(e=>e.disabled=!working||busy);$('filename').textContent=name||'Aucune image importée';$('dimensions').textContent=working?`${working.width} × ${working.height} px`:'';$('resume').hidden=!working;$('undo').disabled=!history.length||busy;$('redo').disabled=!redoHistory.length||busy;$('stage-label').textContent=compare?'ORIGINAL':tool==='compose'?'COMPOSITION':tool==='erase'?'ZONE À SUPPRIMER':'VOTRE IMAGE';const factor=+document.querySelector('[name=scale]:checked').value;$('upscale-size').textContent=working?`${working.width} × ${working.height} → ${working.width*factor} × ${working.height*factor} px`:'Choisissez une image pour voir les dimensions finales.';layerList();}
function snapshot(){return {raster:pngData(working),project:structuredClone(project),mask:pngData(mask),tool};}
function checkpoint(){if(!working)return;redoHistory=[];history.push(snapshot());while(history.length>6||history.reduce((n,s)=>n+s.raster.length+s.mask.length+JSON.stringify(s.project).length,0)>90*1024*1024)history.shift();$('undo').disabled=!history.length;$('redo').disabled=!redoHistory.length;}
async function restore(s){working=await toCanvas(s.raster);mask=await toCanvas(s.mask);project=s.project;editorSelection=null;warp=null;await loadAssets();ensureBase();selectedLayer=project.layers[0]?.id||null;penNodes=[];penClosed=false;detected=[];$('subjects').replaceChildren();draw();update();scheduleSave();}
async function toCanvas(src){const i=await image(src);const c=makeCanvas(i.naturalWidth,i.naturalHeight);c.getContext('2d').drawImage(i,0,0);return c;}
async function loadAssets(){assets.clear();const urls=[project.backgroundImage,...project.layers.filter(l=>l.kind==='image').map(l=>l.data),...project.layers.map(l=>l.maskData)].filter(Boolean);for(const url of new Set(urls))assets.set(url,await image(url));}
async function select(file){if(!file||busy||!ready)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){status('Choisissez une image JPG, PNG ou WEBP.');return;}if(file.size>15*1024*1024){status('Cette image dépasse 15 Mo.');return;}lock(true);try{const url=await dataURL(file),i=await image(url);if(i.naturalWidth*i.naturalHeight>25000000||Math.max(i.naturalWidth,i.naturalHeight)>16384)throw Error('Utilisez une image de moins de 25 mégapixels et 16 384 px de côté.');const next=makeCanvas(i.naturalWidth,i.naturalHeight);next.getContext('2d').drawImage(i,0,0);if(!beginDocument(next.width,next.height))return;source=next;working=makeCanvas(next.width,next.height);working.getContext('2d').drawImage(next,0,0);mask=makeCanvas(next.width,next.height);name=file.name.slice(0,255);sourceData=url;sourceType=file.type;history=[];detected=[];editorSelection=null;warp=null;assets.clear();project={background:null,backgroundImage:null,layers:[]};ensureBase();selectedLayer='base';penNodes=[];penClosed=false;$('subjects').replaceChildren();$('home').hidden=true;$('editor').hidden=false;status('Votre image est prête. Choisissez un outil.');draw();scheduleSave();}catch(e){status(e.message);}finally{lock(false);openTool(tool);}}
function choose(){if(busy||!ready)return;$('file').value='';$('file').click();}
async function run(operation,success){if(!working||busy||!ready)return;lock(true);compare=false;try{const previous=snapshot();const next=await operation();redoHistory=[];history.push(previous);while(history.length>6||history.reduce((n,s)=>n+s.raster.length+s.mask.length+JSON.stringify(s.project).length,0)>90*1024*1024)history.shift();const base=project.layers.find(l=>l.kind==='base');if(base&&next.width!==working.width){base.width=next.width;base.height=next.height;base.scale=1;}working=next;mask=makeCanvas(next.width,next.height);detected=[];$('subjects').replaceChildren();draw();status(success);scheduleSave();}catch(e){console.error(e);status(e.message?.includes('memory')?'La mémoire disponible est insuffisante. Essayez le moteur rapide ou une image plus petite.':e.message||'Le traitement a échoué.');}finally{lock(false);update();}}
function scheduleSave(){if(!desktop||!working||!ready)return;clearTimeout(saveTimer);saveTimer=setTimeout(persist,500);}
async function persist(){if(!desktop||!working||!ready)return;$('saved').textContent='Sauvegarde…';try{captureDocument();const session=serializeDocument(documentRecords.get(activeDocumentId));session.documentId=activeDocumentId;session.documents=[...documentRecords].filter(([id])=>id!==activeDocumentId).map(([id,d])=>({...serializeDocument(d),documentId:id}));session.documentOrder=[...documentRecords.keys()];await desktop.save(session);$('saved').textContent='Sauvegardé sur cet appareil';}catch(e){console.error(e);$('saved').textContent='Sauvegarde impossible. Exportez votre image.';}}
function layerList(){
 const list=$('layer-list');list.replaceChildren();project.layers.slice().reverse().forEach(l=>{const o=document.createElement('option');o.value=l.id;o.textContent=(l.visible===false?'○ ':'● ')+(l.locked?'🔒 ':'')+(l.name|| (l.kind==='text'?l.text.slice(0,35)||'Texte':l.kind==='gradient'?'Dégradé':'Image'));o.selected=l.id===selectedLayer;list.append(o);});
 const l=currentLayer();$('layer-options').hidden=!l;if(!l)return;
 $('layer-name').value=l.name||'';$('layer-visible').textContent=l.visible===false?'Afficher':'Masquer';$('layer-lock').textContent=l.locked?'Déverrouiller':'Verrouiller';
 $('layer-size').max=Math.max(300,Math.ceil(l.scale*100));$('layer-size').value=Math.round(l.scale*100);$('size-value').value=Math.round(l.scale*100);$('layer-rotation').value=l.rotation;$('rotation-value').value=l.rotation;$('layer-opacity').value=Math.round(l.opacity*100);
 $('text-options').hidden=l.kind!=='text';if(l.kind==='text'){$('edit-text').value=l.text;$('text-color').value=l.color;$('font').value=l.font;$('text-size').value=l.fontSize;$('text-weight').value=l.weight||800;$('text-italic').checked=!!l.italic;$('text-bg-enabled').checked=!!l.textBackground;$('text-bg').value=l.textBackground||'#d6ee63';$('text-padding').value=l.padding??12;}
 for(const field of ['brightness','contrast','saturation'])$('adjust-'+field).value=l[field]??100;
 if(l.gradient){$('gradient-start').value=l.gradient.start;$('gradient-end').value=l.gradient.end;$('gradient-mid').value=l.gradient.mid*100;$('gradient-value').value=Math.round(l.gradient.mid*100);}
}
function currentLayer(){return project.layers.find(l=>l.id===selectedLayer);}
function modifyLayer(f){if(busy)return;const l=project.layers.find(l=>l.id===selectedLayer);if(!l||l.locked)return;checkpoint();f(l);draw();update();scheduleSave();}
function newLayer(fields,record=true){if(project.layers.length>=30)throw Error('La composition est limitée à 30 calques.');if(record)checkpoint();const l={id:crypto.randomUUID(),x:working.width/2,y:working.height/2,rotation:0,scale:1,opacity:1,...fields};project.layers.push(l);selectedLayer=l.id;draw();update();scheduleSave();}
function rebuildMask(){mask.getContext('2d').clearRect(0,0,mask.width,mask.height);for(const r of detected)if(r.selected)mask.getContext('2d').drawImage(r.mask,0,0,mask.width,mask.height);drawOverlay();scheduleSave();}
function subjectButtons(){const el=$('subjects');el.replaceChildren();detected.forEach((r,i)=>{const b=document.createElement('button');b.className='button';b.textContent=`Sujet ${i+1}`;b.setAttribute('aria-pressed',String(r.selected));b.onclick=()=>{if(busy)return;checkpoint();r.selected=!r.selected;rebuildMask();subjectButtons();};el.append(b);});}
$('brand').onclick=home;$('home-button').onclick=home;$('resume').onclick=()=>openTool(tool);document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>openTool(b.dataset.tool));['choose','empty-choose','import-header'].forEach(id=>$(id).onclick=choose);$('file').onchange=e=>select(e.target.files[0]);
['dragenter','dragover'].forEach(event=>$('drop').addEventListener(event,e=>{e.preventDefault();if(!busy)$('drop').classList.add('over');}));['dragleave','drop'].forEach(event=>$('drop').addEventListener(event,e=>{e.preventDefault();$('drop').classList.remove('over');if(event==='drop')select(e.dataTransfer.files[0]);}));
$('remove').onclick=()=>run(()=>segment(working,status,$('engine').value),'Le fond est supprimé. Exportez le PNG ou ajoutez un arrière-plan.');$('send-compose').onclick=()=>openTool('compose');$('upscale').onclick=()=>{const factor=+document.querySelector('[name=scale]:checked').value;run(async()=>{const next=await enlarge(working,factor,status);project.layers.forEach(l=>{l.x*=factor;l.y*=factor;l.scale*=factor;});return next;},'Votre image a été agrandie et améliorée.');};document.querySelectorAll('[name=scale]').forEach(e=>e.onchange=update);
$('manual-mode').onclick=()=>{if(busy)return;$('manual-controls').hidden=false;$('auto-controls').hidden=true;$('manual-mode').setAttribute('aria-pressed','true');$('auto-mode').setAttribute('aria-pressed','false');};$('auto-mode').onclick=()=>{if(busy)return;$('manual-controls').hidden=true;$('auto-controls').hidden=false;$('manual-mode').setAttribute('aria-pressed','false');$('auto-mode').setAttribute('aria-pressed','true');};$('brush').oninput=()=>{$('brush-value').value=$('brush').value;};$('clear-mask').onclick=()=>{if(!working||busy)return;checkpoint();mask.getContext('2d').clearRect(0,0,mask.width,mask.height);detected.forEach(r=>r.selected=false);subjectButtons();drawOverlay();};
$('detect').onclick=async()=>{if(!working||busy)return;lock(true);try{const cutout=await segment(working,status,$('auto-engine').value);detected=(await regions(cutout)).map(r=>({...r,selected:false}));subjectButtons();status(detected.length?'Cliquez sur les sujets à supprimer, puis confirmez la suppression.':'Aucun sujet distinct détecté. Utilisez le pinceau.');}catch(e){status(e.message);}finally{lock(false);}};$('erase').onclick=()=>run(()=>fill(working,mask,status,$('erase-engine').value,Math.max(0,Math.min(40,+$('mask-margin').value||0))),'La sélection a été supprimée. Vérifiez le résultat et annulez si nécessaire.');
$('background').onchange=()=>{if(!working||busy)return;checkpoint();project.background=$('background').value;draw();scheduleSave();};$('transparent').onclick=()=>{if(!working||busy)return;checkpoint();project.background=null;project.backgroundImage=null;draw();scheduleSave();};$('background-image').onclick=()=>{assetKind='background';$('asset-file').value='';$('asset-file').click();};$('add-image').onclick=()=>{assetKind='layer';$('asset-file').value='';$('asset-file').click();};$('asset-file').onchange=async e=>{const f=e.target.files[0];if(!f||busy||!working)return;lock(true);try{if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>15*1024*1024)throw Error('Choisissez un JPG, PNG ou WEBP de moins de 15 Mo.');const url=await dataURL(f),i=await image(url);if(i.naturalWidth*i.naturalHeight>25000000)throw Error('Cette image dépasse 25 mégapixels.');assets.set(url,i);if(assetKind==='background'){checkpoint();project.backgroundImage=url;draw();scheduleSave();}else{const k=Math.min(1,working.width*.65/i.naturalWidth,working.height*.65/i.naturalHeight);newLayer({kind:'image',data:url,name:f.name.slice(0,255),width:i.naturalWidth*k,height:i.naturalHeight*k});}status('Image ajoutée à la composition.');}catch(e){status(e.message);}finally{lock(false);update();}};
$('add-text').onclick=()=>{if(!working||busy)return;const text=$('text').value.trim();if(!text){status('Saisissez le texte à ajouter.');return;}try{const ctx=screen.getContext('2d');let fontSize=Math.max(18,working.width*.08);ctx.font=`800 ${fontSize}px Syne`;const width=ctx.measureText(text).width;if(width>working.width*.8)fontSize*=working.width*.8/width;newLayer({kind:'text',text,font:'Syne',fontSize,color:'#111111'});status('Texte ajouté. Vous pouvez le déplacer dans l’image.');}catch(e){status(e.message);}};$('layer-list').onchange=()=>{selectedLayer=$('layer-list').value;drawOverlay();layerList();};
[['layer-size','scale',100],['layer-rotation','rotation',1],['layer-opacity','opacity',100]].forEach(([id,field,divisor])=>{$(id).onpointerdown=()=>checkpoint();$(id).oninput=()=>{const l=project.layers.find(l=>l.id===selectedLayer);if(!l||l.locked||busy)return;l[field]=+$(id).value/divisor;draw();$('size-value').value=Math.round(l.scale*100);$('rotation-value').value=l.rotation;scheduleSave();};$(id).onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))checkpoint();};});bindText();$('layer-delete').onclick=()=>{if(!selectedLayer||busy)return;checkpoint();project.layers=project.layers.filter(l=>l.id!==selectedLayer);selectedLayer=null;draw();update();scheduleSave();};[['layer-up',1],['layer-down',-1]].forEach(([id,step])=>$(id).onclick=()=>{const i=project.layers.findIndex(l=>l.id===selectedLayer),j=i+step;if(busy||i<0||j<0||j>=project.layers.length)return;checkpoint();[project.layers[i],project.layers[j]]=[project.layers[j],project.layers[i]];draw();update();scheduleSave();});
$('original').onclick=()=>{if(!working||busy)return;compare=!compare;$('original').textContent=compare?'Voir les modifications':'Voir l’original';draw();update();};$('undo').onclick=async()=>{if(busy||!history.length)return;lock(true);try{await restore((()=>{redoHistory.push(snapshot());return history.pop();})());status('Dernière modification annulée.');}finally{lock(false);update();}};$('reset').onclick=()=>{if(!working||busy)return;checkpoint();working=makeCanvas(source.width,source.height);working.getContext('2d').drawImage(source,0,0);mask=makeCanvas(source.width,source.height);project={background:null,backgroundImage:null,layers:[]};ensureBase();selectedLayer='base';penNodes=[];penClosed=false;draw();update();scheduleSave();status('Image originale restaurée.');};
$('export').onclick=async()=>{if(!working||busy)return;lock(true);try{compare=false;draw();await document.fonts.ready;const out=makeCanvas(working.width,working.height);render(out);const png=await blob(out),filename=name.replace(/\.[^.]+$/,'')+'-'+tool+'.png';if(desktop){const result=await desktop.exportPng(await png.arrayBuffer(),filename);status(result.saved?'PNG exporté.':'Export annulé.');}else{const url=URL.createObjectURL(png),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);status('PNG exporté.');}}catch(e){status(e.message);}finally{lock(false);}};
let pointer;
let position=e=>{const r=overlay.getBoundingClientRect();return {x:(e.clientX-r.left)/r.width*overlay.width,y:(e.clientY-r.top)/r.height*overlay.height};};
function brush(p,last=p){const ctx=mask.getContext('2d');ctx.globalCompositeOperation=$('mask-eraser').checked?'destination-out':'source-over';ctx.strokeStyle='#f01813';ctx.fillStyle='#f01813';ctx.lineWidth=+$('brush').value;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(p.x,p.y);ctx.stroke();ctx.beginPath();ctx.arc(p.x,p.y,+$('brush').value/2,0,Math.PI*2);ctx.fill();ctx.globalCompositeOperation='source-over';drawOverlay();}
function hitLayer(p){for(const l of project.layers.slice().reverse()){if(l.visible===false||l.locked)continue;const dx=p.x-l.x,dy=p.y-l.y,a=-l.rotation*Math.PI/180,x=(dx*Math.cos(a)-dy*Math.sin(a))/l.scale,y=(dx*Math.sin(a)+dy*Math.cos(a))/l.scale,b=layerBounds(l);if(Math.abs(x)<=b.w/2&&Math.abs(y)<=b.h/2)return l;}return null;}
overlay.onpointerdown=e=>{if(busy||!working||compare||e.button!==0)return;const p=position(e);if(tool==='erase'){if(!$('auto-controls').hidden&&detected.length){for(let i=0;i<detected.length;i++){const r=detected[i],x=Math.min(r.mask.width-1,Math.max(0,Math.floor(p.x/working.width*r.mask.width))),y=Math.min(r.mask.height-1,Math.max(0,Math.floor(p.y/working.height*r.mask.height)));if(r.mask.getContext('2d').getImageData(x,y,1,1).data[3]){checkpoint();r.selected=!r.selected;rebuildMask();subjectButtons();return;}}}checkpoint();pointer={id:e.pointerId,p};brush(p);}else if(tool==='compose'){const l=hitLayer(p);selectedLayer=l?.id||null;layerList();drawOverlay();if(!l)return;checkpoint();pointer={id:e.pointerId,p,layer:l.id,x:l.x,y:l.y};}else return;overlay.setPointerCapture(e.pointerId);e.preventDefault();};
