const fitBeforeStudio=fit;fit=function(){fitBeforeStudio();if(!working)return;const wrap=$('canvas-wrap');wrap.style.transform=`translate(${panOffset.x}px,${panOffset.y}px) scale(${zoomFactor})`;$('zoom-value').textContent=Math.round(zoomFactor*100)+' %';};
