$('new-document').onclick=()=>{if(busy)return;const w=Math.min(8192,Math.max(16,+$('document-width').value||1024)),h=Math.min(8192,Math.max(16,+$('document-height').value||768));if(w*h>25000000){status('Maximum 25 mégapixels.');return;}if(!beginDocument(w,h))return;history=[];redoHistory=[];assets.clear();source=makeCanvas(w,h);working=makeCanvas(w,h);mask=makeCanvas(w,h);sourceData=pngData(source);sourceType='image/png';name='Sans titre.png';project={background:null,backgroundImage:null,layers:[]};ensureBase();selectedLayer='base';editorSelection=null;warp=null;zoomFactor=1;panOffset={x:0,y:0};openTool('compose');activateStudio('paint');draw();update();scheduleSave();};
$('document-resize').onclick=()=>{if(!working||busy)return;const w=Math.min(8192,Math.max(16,+$('document-width').value||working.width)),h=Math.min(8192,Math.max(16,+$('document-height').value||working.height));if(w*h>25000000){status('Maximum 25 mégapixels.');return;}checkpoint();const sx=w/working.width,sy=h/working.height,next=makeCanvas(w,h);next.getContext('2d').drawImage(working,0,0,w,h);working=next;for(const l of project.layers){l.x*=sx;l.y*=sy;if(l.kind==='base'){l.width=w;l.height=h;}else{l.scale*=Math.min(sx,sy);}}mask=makeCanvas(w,h);editorSelection=null;warp=null;draw();update();scheduleSave();};
