function selectionPixels(){return editorSelection?.width===working.width&&editorSelection?.height===working.height?editorSelection.getContext('2d').getImageData(0,0,working.width,working.height).data:null;}
$('select-all').onclick=()=>{if(!working)return;const c=makeCanvas(working.width,working.height);c.getContext('2d').fillStyle='#f01813';c.getContext('2d').fillRect(0,0,c.width,c.height);selectionCombine(c);};$('select-none').onclick=()=>{editorSelection=null;drawOverlay();};
