function selectedRasterAction(mode){if(!editorSelection||busy)return;try{const {layer,canvas:c}=activeWorldRaster();checkpoint();const ctx=c.getContext('2d');ctx.globalCompositeOperation=mode==='delete'?'destination-out':'destination-in';ctx.drawImage(editorSelection,0,0);ctx.globalCompositeOperation='source-over';if(mode==='delete')setWorldRaster(layer,c);else{const data=pngData(c);assets.set(data,c);newLayer({kind:'image',name:'Sélection',width:c.width,height:c.height,data},false);}draw();update();scheduleSave();}catch(e){status(e.message);}}
$('select-to-layer').onclick=()=>selectedRasterAction('copy');$('select-delete').onclick=()=>selectedRasterAction('delete');
