$('filter-apply').onclick=()=>{if(!working||busy)return;try{const {layer,canvas:c}=activeWorldRaster(),ctx=c.getContext('2d'),p=ctx.getImageData(0,0,c.width,c.height),kind=$('pixel-filter').value;const changed=filterPixels(p.data,c.width,c.height,kind,+$('filter-amount').value);checkpoint();p.data.set(compositePixels(p.data,changed,selectionPixels()));ctx.putImageData(p,0,0);setWorldRaster(layer,c);draw();update();scheduleSave();refreshHistogram();status('Filtre appliqué au calque : '+$('pixel-filter').selectedOptions[0].textContent);}catch(e){status(e.message);}};
function refreshHistogram(){if(!working)return;const bins=histogram(screen.getContext('2d').getImageData(0,0,screen.width,screen.height).data),ctx=$('histogram').getContext('2d');ctx.clearRect(0,0,256,90);ctx.fillStyle='#111';ctx.fillRect(0,0,256,90);const max=Math.max(1,...bins[3]);for(let c=0;c<3;c++){ctx.strokeStyle=['#ff685e','#d6ee63','#67b8ff'][c];ctx.beginPath();for(let i=0;i<256;i++){const y=88-Math.min(85,Math.sqrt(bins[c][i]/max)*85);i?ctx.lineTo(i,y):ctx.moveTo(i,y);}ctx.stroke();}}
$('histogram-refresh').onclick=refreshHistogram;$('show-grid').onchange=drawOverlay;$('grid-step').onchange=drawOverlay;
