const layersBeforeStudio=layerList;layerList=function(){layersBeforeStudio();const l=currentLayer();if(l)$('blend-mode').value=l.blend||'source-over';};
const overlayBeforeStudio=drawOverlay;drawOverlay=function(){overlayBeforeStudio();if(!working||tool!=='compose'||compare)return;const ctx=overlay.getContext('2d');ctx.save();if($('show-grid').checked){const step=Math.max(4,+$('grid-step').value||32);ctx.strokeStyle='#8888';ctx.lineWidth=working.width/Math.max(1,overlay.getBoundingClientRect().width);ctx.beginPath();for(let x=0;x<working.width;x+=step){ctx.moveTo(x,0);ctx.lineTo(x,working.height);}for(let y=0;y<working.height;y+=step){ctx.moveTo(0,y);ctx.lineTo(working.width,y);}ctx.stroke();}if(editorSelection&&editorSelection.width===working.width){ctx.globalAlpha=.22;ctx.drawImage(editorSelection,0,0);ctx.globalAlpha=1;}if(studioPointer?.preview){ctx.globalAlpha=.4;ctx.drawImage(studioPointer.preview,0,0);ctx.globalAlpha=1;}if(studioPointer?.mode==='measure'){const {start,end}=studioPointer;ctx.strokeStyle='#f01813';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(start.x,start.y);ctx.lineTo(end.x,end.y);ctx.stroke();}if(warp){ctx.strokeStyle='#f01813';ctx.fillStyle='#d6ee63';ctx.lineWidth=2;for(const tri of warp.triangles){ctx.beginPath();tri.forEach((n,i)=>{const p=warp.points[n];i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y);});ctx.closePath();ctx.stroke();}for(const p of warp.points){ctx.beginPath();ctx.arc(p.x,p.y,7,0,Math.PI*2);ctx.fill();ctx.stroke();}}if(cloneAnchor&&['clone','heal'].includes(editTool)){ctx.strokeStyle='#f01813';ctx.lineWidth=2;ctx.strokeRect(cloneAnchor.x-6,cloneAnchor.y-6,12,12);}ctx.restore();};
function drawShape(ctx,r,kind){ctx.beginPath();const cx=r.x+r.w/2,cy=r.y+r.h/2;if(kind==='ellipse'||kind==='donut'){ctx.ellipse(cx,cy,r.w/2,r.h/2,0,0,Math.PI*2);if(kind==='donut')ctx.ellipse(cx,cy,r.w*.28,r.h*.28,0,0,Math.PI*2,true);}else if(kind==='rounded')ctx.roundRect(r.x,r.y,r.w,r.h,Math.min(r.w,r.h)/5);else if(kind==='heart'){ctx.moveTo(cx,r.y+r.h);ctx.bezierCurveTo(r.x-r.w*.3,r.y+r.h*.4,r.x,r.y-r.h*.25,cx,r.y+r.h*.22);ctx.bezierCurveTo(r.x+r.w,r.y-r.h*.25,r.x+r.w*1.3,r.y+r.h*.4,cx,r.y+r.h);}else if(kind==='arrow'){for(const [i,p]of [[0,.32],[.58,.32],[.58,0],[1,.5],[.58,1],[.58,.68],[0,.68]].entries())i?ctx.lineTo(r.x+p[0]*r.w,r.y+p[1]*r.h):ctx.moveTo(r.x+p[0]*r.w,r.y+p[1]*r.h);ctx.closePath();}else if(kind==='cloud'){for(const [x,y,rx,ry] of [[.25,.6,.25,.3],[.5,.4,.3,.4],[.78,.6,.22,.3]]){ctx.moveTo(r.x+(x+rx)*r.w,r.y+y*r.h);ctx.ellipse(r.x+x*r.w,r.y+y*r.h,rx*r.w,ry*r.h,0,0,Math.PI*2);}}else if(kind==='line'){ctx.moveTo(r.x,r.y);ctx.lineTo(r.x+r.w,r.y+r.h);}else if(['polygon','star','triangle','diamond'].includes(kind)){const n=kind==='triangle'?3:kind==='diamond'?4:Math.max(3,Math.min(30,+$('shape-sides').value||5)),count=kind==='star'?n*2:n;for(let i=0;i<count;i++){const angle=-Math.PI/2+i*Math.PI*2/count,k=kind==='star'&&i%2?.45:1,x=cx+Math.cos(angle)*r.w/2*k,y=cy+Math.sin(angle)*r.h/2*k;i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.closePath();}else ctx.rect(r.x,r.y,r.w,r.h);}
