 if(editTool==='warp'&&warp){const idx=warp.points.findIndex(n=>Math.hypot(n.x-p.x,n.y-p.y)<15*working.width/overlay.getBoundingClientRect().width);if(idx>=0){studioPointer={mode:'warp',index:idx};overlay.setPointerCapture(e.pointerId);}return;}
 if(['magic','bucket'].includes(editTool)){try{const {layer,canvas:c}=editTool==='magic'&&$('selection-sample-all').checked?{layer:currentLayer(),canvas:working}:activeWorldRaster(),ctx=c.getContext('2d'),reference=makeCanvas(c.width,c.height);if(editTool==='magic'&&$('selection-sample-all').checked)render(reference);else reference.getContext('2d').drawImage(c,0,0);const pixels=reference.getContext('2d').getImageData(0,0,c.width,c.height),selected=floodSelection(pixels.data,c.width,c.height,p.x,p.y,+$('selection-tolerance').value,$('selection-contiguous').checked);if(editTool==='magic')selectionCombine(selectionFromPixels(selected),mode);else{const color=$('paint-color').value.match(/[0-9a-f]{2}/gi).map(x=>parseInt(x,16)),sel=selectionPixels();checkpoint();for(let i=0;i<pixels.data.length;i+=4)if(selected[i+3]&&(!sel||sel[i+3])){pixels.data[i]=color[0];pixels.data[i+1]=color[1];pixels.data[i+2]=color[2];pixels.data[i+3]=255;}ctx.putImageData(pixels,0,0);setWorldRaster(layer,c);draw();update();scheduleSave();}}catch(err){status(err.message);}return;}
 if(selectionTools.includes(editTool)){const reference=makeCanvas(working.width,working.height);if($('selection-sample-all')?.checked)render(reference);else{try{reference.getContext('2d').drawImage(activeWorldRaster().canvas,0,0);}catch(err){status(err.message);return;}}studioPointer={mode:'selection',kind:editTool,start:p,points:[p],combine:mode,reference:reference.getContext('2d').getImageData(0,0,reference.width,reference.height).data,last:p,preview:makeCanvas(working.width,working.height)};overlay.setPointerCapture(e.pointerId);updateSelection(p);return;}
 if(retouchTools.includes(editTool)){if(e.altKey&&['clone','heal'].includes(editTool)){cloneAnchor=p;drawOverlay();status('Source définie. Peignez sur la zone à corriger.');return;}if(['clone','heal'].includes(editTool)&&!cloneAnchor){status('Alt + clic pour choisir une source sur ce calque.');return;}try{const {layer,canvas:c}=activeWorldRaster(),original=makeCanvas(c.width,c.height);original.getContext('2d').drawImage(c,0,0);checkpoint();studioPointer={mode:'retouch',tool:editTool,layer,canvas:c,original,start:p,last:p};overlay.setPointerCapture(e.pointerId);paintRetouch(p);}catch(err){status(err.message);}return;}
