function updateSelection(p){const st=studioPointer,ctx=st.preview.getContext('2d');ctx.fillStyle='#f01813';ctx.strokeStyle='#f01813';if(st.kind==='selection-brush'){const radius=+$('retouch-size').value/2,steps=Math.max(1,Math.ceil(Math.hypot(p.x-st.last.x,p.y-st.last.y)/Math.max(1,radius/3))),old={...st.last};for(let n=1;n<=Math.min(steps,120);n++){const q={x:old.x+(p.x-old.x)*n/steps,y:old.y+(p.y-old.y)*n/steps};if($('selection-smart').checked){const patch=smartBrushSelection(st.reference,working.width,working.height,q.x,q.y,radius,+$('selection-tolerance').value);const c=makeCanvas(patch.width,patch.height);c.getContext('2d').putImageData(new ImageData(patch.data,patch.width,patch.height),0,0);ctx.drawImage(c,patch.x,patch.y);}else{ctx.beginPath();ctx.arc(q.x,q.y,radius,0,Math.PI*2);ctx.fill();}}st.last=p;}else{ctx.clearRect(0,0,st.preview.width,st.preview.height);const r=rectangle(st.start,p);ctx.beginPath();if(st.kind==='select-rect')ctx.rect(r.x,r.y,r.w,r.h);else if(st.kind==='select-ellipse')ctx.ellipse(r.x+r.w/2,r.y+r.h/2,r.w/2,r.h/2,0,0,Math.PI*2);else{st.points.push(p);st.points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();}ctx.fill();}drawOverlay();}
