function closeDocument(id){if(busy)return;captureDocument();documentRecords.delete(id);if(id===activeDocumentId){const next=documentRecords.keys().next().value;if(next){activeDocumentId='';switchDocument(next,false);}else{source=working=mask=null;sourceData='';sourceType='';name='';assets.clear();history=[];redoHistory=[];project={background:null,backgroundImage:null,layers:[]};editorSelection=null;selectedLayer=null;activeDocumentId=crypto.randomUUID();$('canvas-wrap').hidden=true;$('empty').hidden=false;update();}}else renderDocumentTabs();if(working)scheduleSave();else if(desktop&&ready){clearTimeout(saveTimer);desktop.save(null).catch(e=>status(e.message));}}
