const layerClipboardTarget=()=>!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.activeElement.isContentEditable&&tool==='compose'&&!busy;
document.addEventListener('copy',e=>{if(!layerClipboardTarget()||!copySelectedLayer())return;e.preventDefault();e.clipboardData?.setData('text/plain','CUTOUT · '+(layerClipboard.name||layerClipboard.text||'Calque'));});
document.addEventListener('paste',e=>{if(!layerClipboardTarget()||!layerClipboard)return;e.preventDefault();pasteCopiedLayer();});
const eraseTargetLabel=document.createElement('label');eraseTargetLabel.innerHTML='Source à retoucher<select id="erase-source"><option value="base">Image principale</option><option value="selected">Calque image sélectionné</option><option value="merged">Tous les calques · Retouche séparée</option></select>';$('erase-engine').parentElement.insertBefore(eraseTargetLabel,$('erase-engine'));
const renderBeforeErase7=render;render=function(target,withProject=tool==='compose'){if(tool==='erase'&&$('erase-source').value==='merged')return renderBeforeErase7(target,true);if(tool==='erase'&&$('erase-source').value==='selected'){target.getContext('2d').clearRect(0,0,target.width,target.height);const l=currentLayer();if(l)drawLayer(target.getContext('2d'),{...l,visible:true});return;}return renderBeforeErase7(target,withProject);};$('erase-source').onchange=()=>draw();
const transfer7=$('select-to-mask').onclick;$('select-to-mask').onclick=()=>{const l=currentLayer();$('erase-source').value=l?.kind==='base'?'base':l?.kind==='image'?'selected':'merged';transfer7();};
$('erase').onclick=async()=>{if(!working||busy||!ready)return;const target=$('erase-source').value,l=currentLayer();if(target==='selected'&&(!l||l.locked||!['base','image'].includes(l.kind))){status('Choisissez un calque image déverrouillé, ou retouchez tous les calques.');return;}if(target==='merged'&&project.layers.length>=30){status('Maximum trente calques.');return;}lock(true);try{const before=snapshot(),src=target==='selected'?activeWorldRaster().canvas:target==='merged'?(()=>{const c=makeCanvas(working.width,working.height);renderBeforeErase7(c,true);return c;})():working,margin=Math.max(0,Math.min(40,+$('mask-margin').value||0)),result=await fill(src,mask,status,$('erase-engine').value,margin);redoHistory=[];history.push(before);while(history.length>6||history.reduce((n,s)=>n+s.raster.length+s.mask.length+JSON.stringify(s.project).length,0)>90*1024*1024)history.shift();if(target==='selected')setWorldRaster(l,result);else if(target==='merged'){const p=mask.getContext('2d').getImageData(0,0,mask.width,mask.height),bits=new Uint8Array(mask.width*mask.height);for(let i=0;i<bits.length;i++)bits[i]=p.data[i*4+3]>10?1:0;const expanded=dilateBinary(bits,mask.width,mask.height,margin);for(let i=0;i<bits.length;i++){p.data[i*4]=255;p.data[i*4+3]=expanded[i]?255:0;}const coverage=makeCanvas(mask.width,mask.height);coverage.getContext('2d').putImageData(p,0,0);const ctx=result.getContext('2d');ctx.globalCompositeOperation='destination-in';ctx.drawImage(coverage,0,0);ctx.globalCompositeOperation='source-over';const data=pngData(result);assets.set(data,result);newLayer({kind:'image',name:'Retouche contextuelle',data,width:result.width,height:result.height},false);}else working=result;mask=makeCanvas(working.width,working.height);detected=[];draw();update();scheduleSave();status('Retouche appliquée. Vous pouvez annuler ou masquer le calque de retouche.');}catch(e){status(e.message);}finally{lock(false);}};

desktop?.onEditCommand?.(action=>{if(busy)return;const editing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||document.activeElement.isContentEditable;if(editing&&['copy','paste','cut','undo','redo','selectAll'].includes(action)){desktop.nativeEdit(action);return;}const commands={copy:copySelectedLayer,paste:pasteCopiedLayer,cut:()=>{if(copySelectedLayer())$('layer-delete').click();},undo:()=>$('undo').click(),redo:()=>$('redo').click(),duplicate:()=>$('layer-duplicate').click(),new:()=>$('new-document').click(),open:choose,save:persist,export:()=>$('export').click(),selectAll:()=>$('select-all').click(),deselect:()=>$('select-none').click()};commands[action]?.();});
